def topoSort(V, adj):
    in_deg = [0]*V
    for u in range(V):
        for v in adj[u]: in_deg[v] += 1
    queue = deque([i for i in range(V) if in_deg[i]==0])
    result = []
    while queue:
        node = queue.popleft()
        result.append(node)
        for nb in adj[node]:
            in_deg[nb] -= 1
            if in_deg[nb] == 0: queue.append(nb)
    return result

