def countSCC(V, adj):
    visited = [False]*V
    order = []
    def dfs1(node):
        visited[node] = True
        for nb in adj[node]:
            if not visited[nb]: dfs1(nb)
        order.append(node)
    for i in range(V):
        if not visited[i]: dfs1(i)
    radj = [[] for _ in range(V)]
    for u in range(V):
        for v in adj[u]: radj[v].append(u)
    visited = [False]*V
    count = 0
    def dfs2(node):
        visited[node] = True
        for nb in radj[node]:
            if not visited[nb]: dfs2(nb)
    for node in reversed(order):
        if not visited[node]:
            dfs2(node)
            count += 1
    return count
